from mcp.server.fastmcp import FastMCP

mcp = FastMCP("orders")

@mcp.tool()
def get_order_status(order_id: str) -> dict:
    """Look up the current fulfilment status of one order.

    Use when the user asks where an order is, whether it shipped,
    or for its tracking number. Requires the full order id (e.g. ORD-91422).
    Does not modify anything.
    """
    if not order_id.startswith("ORD-"):
        raise ValueError("order_id must look like ORD-12345")
    return lookup(order_id)
